toolScript:
// --- GAME DATA ---
        const locations = [
            { name: "The Great Pyramid of Giza", coords: [29.9792, 31.1342] },
            { name: "Eiffel Tower, Paris", coords: [48.8584, 2.2945] },
            { name: "Statue of Liberty, NYC", coords: [40.6892, -74.0445] },
            { name: "Taj Mahal, India", coords: [27.1751, 78.0421] },
            { name: "Sydney Opera House", coords: [-33.8568, 151.2153] },
            { name: "Colosseum, Rome", coords: [41.8902, 12.4922] },
            { name: "Machu Picchu, Peru", coords: [-13.1631, -72.5450] },
            { name: "Burj Khalifa, Dubai", coords: [25.1972, 55.2744] },
            { name: "Mount Fuji, Japan", coords: [35.3606, 138.7274] },
            { name: "Central Park, NYC", coords: [40.7829, -73.9654] },
            { name: "Palm Jumeirah, Dubai", coords: [25.1124, 55.1390] },
            { name: "Golden Gate Bridge, SF", coords: [37.8199, -122.4783] },
            { name: "Stonehenge, UK", coords: [51.1789, -1.8262] },
            { name: "Niagara Falls", coords: [43.0962, -79.0377] },
            { name: "Forbidden City, Beijing", coords: [39.9163, 116.3972] },
            { name: "Christ the Redeemer, Rio", coords: [-22.9519, -43.2105] },
            { name: "Grand Canyon (South Rim)", coords: [36.0544, -112.1401] },
            { name: "Venice, Italy", coords: [45.4408, 12.3155] },
            { name: "Pentagon, USA", coords: [38.8719, -77.0563] },
            { name: "Burning Man (Black Rock City)", coords: [40.7864, -119.2065] },
            { name: "Angkor Wat, Cambodia", coords: [13.4125, 103.8670] },
            { name: "Acropolis of Athens", coords: [37.9715, 23.7257] },
            { name: "Area 51", coords: [37.2343, -115.8067] },
            { name: "Everest Base Camp", coords: [28.0026, 86.8528] },
            { name: "Uluru (Ayers Rock)", coords: [-25.3444, 131.0369] }
        ];
        // --- STATE ---
        let map;
        let currentLocIndex;
        let streak = 0;
        let bestStreak = 0;
        let isRoundActive = false;
        // --- INIT MAP ---
        function initMap() {
            // Esri World Imagery - Satellite Only (No labels)
            map = L.map('map', {
                zoomControl: false,
                attributionControl: true,
                dragging: true,
                scrollWheelZoom: true,
                doubleClickZoom: true,
                touchZoom: true
            });
            L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
                attribution: 'Tiles &copy; Esri &mdash; Source: Esri, i-cubed, USDA, USGS, AEX, GeoEye, Getmapping, Aerogrid, IGN, IGP, UPR-EGP, and the GIS User Community',
                maxZoom: 19
            }).addTo(map);
        }
        function startGame() {
            document.getElementById('start-screen').style.display = 'none';
            document.getElementById('options-container').style.display = 'grid';
            if (!map) initMap();
            streak = 0;
            updateScoreboard();
            nextRound();
        }
        function nextRound() {
            isRoundActive = true;
            document.getElementById('next-btn').style.display = 'none';
            // Pick random location
            const loc = locations[Math.floor(Math.random() * locations.length)];
            currentLocIndex = loc;
            // Set map view (High zoom to make it immersive)
            map.setView(loc.coords, 16);
            // Generate Options (1 correct, 3 random wrong)
            const options = generateOptions(loc);
            renderOptions(options, loc.name);
        }
        function generateOptions(correctLoc) {
            let pool = locations.filter(l => l.name !== correctLoc.name);
            // Shuffle pool
            pool.sort(() => 0.5 - Math.random());
            // Take 3 wrong
            let opts = pool.slice(0, 3);
            opts.push(correctLoc);
            // Shuffle final 4
            return opts.sort(() => 0.5 - Math.random());
        }
        function renderOptions(options, correctName) {
            const container = document.getElementById('options-container');
            container.innerHTML = ''; // Clear
            options.forEach(opt => {
                const btn = document.createElement('button');
                btn.className = 'option-btn';
                btn.innerText = opt.name;
                btn.onclick = () => handleGuess(btn, opt.name, correctName);
                container.appendChild(btn);
            });
        }
        function handleGuess(btn, guessName, correctName) {
            if (!isRoundActive) return;
            isRoundActive = false;
            const buttons = document.querySelectorAll('.option-btn');
            if (guessName === correctName) {
                // Correct
                btn.classList.add('option-correct');
                streak++;
                if (streak > bestStreak) bestStreak = streak;
                fireConfetti();
            } else {
                // Wrong
                btn.classList.add('option-wrong');
                streak = 0;
                // Highlight correct one
                buttons.forEach(b => {
                    if (b.innerText === correctName) b.classList.add('option-correct');
                });
            }
            updateScoreboard();
            document.getElementById('next-btn').style.display = 'block';
            // Slow zoom out for dramatic effect
            map.flyTo(currentLocIndex.coords, 14, { duration: 2 });
        }
        function updateScoreboard() {
            document.getElementById('streak-val').innerText = streak;
            document.getElementById('best-val').innerText = bestStreak;
        }
        // --- SIMPLE CONFETTI EFFECT ---
        function fireConfetti() {
            for (let i = 0; i < 30; i++) {
                createParticle(window.innerWidth / 2, window.innerHeight / 2);
            }
        }
        function createParticle(x, y) {
            const colors = ['#EE6C4D', '#3b82f6', '#22c55e', '#f59e0b'];
            const particle = document.createElement('div');
            particle.style.position = 'fixed';
            particle.style.width = Math.random() * 8 + 4 + 'px';
            particle.style.height = Math.random() * 8 + 4 + 'px';
            particle.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
            particle.style.left = x + 'px';
            particle.style.top = y + 'px';
            particle.style.borderRadius = '50%';
            particle.style.pointerEvents = 'none';
            particle.style.zIndex = '9999';
            document.body.appendChild(particle);
            // Random destination
            const destX = (Math.random() - 0.5) * 400;
            const destY = (Math.random() - 0.5) * 400;
            const animation = particle.animate([
                { transform: `translate(0,0) scale(1)`, opacity: 1 },
                { transform: `translate(${destX}px, ${destY}px) scale(0)`, opacity: 0 }
            ], {
                duration: 1000 + Math.random() * 500,
                easing: 'cubic-bezier(0, .9, .57, 1)'
            });
            animation.onfinish = () => particle.remove();
        }
        // --- SCROLL LOGIC ---
